    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())
    s, t = map(int, lines[1].split())
    edges = []
    for i in range(m):
        parts = list(map(int, lines[2 + i].split()))
        edges.append(parts)  # [u, v, w]

    # Build adjacency list
    adj = [[] for _ in range(n + 1)]
    for i, (u, v, w) in enumerate(edges):
        adj[u].append((v, i))
        adj[v].append((u, i))

    def is_connected(edges_to_remove):
        """Check if s and t are connected using BFS with some edges removed"""
        if edges_to_remove is None:
            selected_indices = [i for i in range(m)]
        else:
            selected_indices = [i for i in range(m) if i not in edges_to_remove]

        adj_bfs = [[] for _ in range(n + 1)]
        for i, (u, v, w) in enumerate(edges):
            if i in selected_indices:
                adj_bfs[u].append(v)
                adj_bfs[v].append(u)

        visited = [False] * (n + 1)
        queue = [s]
        visited[s] = True

        idx = 0
        while idx < len(queue):
            current = queue[idx]
            idx += 1

            if current == t:
                return True

            for neighbor in adj_bfs[current]:
                if not visited[neighbor]:
                    visited[neighbor] = True
                    queue.append(neighbor)

        return False

    # Check if already disconnected
    original_adj = [[] for _ in range(n + 1)]
    for i, (u, v, w) in enumerate(edges):
        original_adj[u].append(v)
        original_adj[v].append(u)

    visited = [False] * (n + 1)
    queue = [s]
    visited[s] = True

    idx = 0
    while idx < len(queue):
        current = queue[idx]
        idx += 1
        if current == t:
            break
        for neighbor in original_adj[current]:
            if not visited[neighbor]:
                visited[neighbor] = True
                queue.append(neighbor)

    if not visited[t]:
        return "0\n0\n"

    # Try removing 1 edge
    min_cost = float('inf')
    best_edges = None

    for i in range(m):
        if is_connected({i}):
            cost = edges[i][2]
            if cost < min_cost:
                min_cost = cost
                best_edges = (i + 1,)

    if best_edges:
        c = len(best_edges)
        cost = min_cost
        edges_list = list(best_edges)
        return f"{cost}\n{c}\n{' '.join(map(str, edges_list))}"

    # Try removing 2 edges
    for i in range(m):
        for j in range(i + 1, m):
            if edges[i][0] == edges[i][1] or edges[j][0] == edges[j][1]:
                continue

            if is_connected({i, j}):
                cost = edges[i][2] + edges[j][2]
                if cost < min_cost:
                    min_cost = cost
                    best_edges = (i + 1, j + 1)

    if best_edges:
        c = len(best_edges)
        cost = min_cost
        edges_list = list(best_edges)
        return f"{cost}\n{c}\n{' '.join(map(str, edges_list))}"

    return "-1"

