def solution(input_data):
    lines = input_data.strip().split('\n')
    n, k = map(int, lines[0].split())
    p = list(map(int, lines[1].split()))

    # Parse pairs (remaining lines after prerequisites)
    pairs = []
    offset = 2
    for i in range(k):
        line = lines[offset + i]
        x, y = map(int, line.split())
        pairs.append((x, y))

    # Build expanded edges: prerequisite relations and implicit constraints from special pairs
    expanded_edges = set()

    for t in range(1, n + 1):
        prereq_t = p[t - 1]
        if prereq_t != 0:
            expanded_edges.add((prereq_t, t))

    for x, y in pairs:
        prereq_y = p[y - 1]
        if prereq_y != 0 and prereq_y != x:
            expanded_edges.add((prereq_y, x))

    # Build adjacency and compute in-degrees
    in_degree = [0] * (n + 1)
    expanded_graph = [[] for _ in range(n + 1)]
    for a, b in expanded_edges:
        expanded_graph[a].append(b)
        in_degree[b] += 1

    # Topological sort using Kahn's algorithm
    queue = deque()
    for i in range(1, n + 1):
        if in_degree[i] == 0:
            queue.append(i)

    result = []
    while queue:
        node = queue.popleft()
        result.append(node)
        for neighbor in expanded_graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if len(result) != n:
        return "\n0\n"

    # Verify adjacency constraints
    topic_pos = {topic: i + 1 for i, topic in enumerate(result)}
    for x, y in pairs:
        if topic_pos[y] != topic_pos[x] + 1:
            return "\n0\n"

    return "\n" + " ".join(map(str, result)) + "\n"

