    n, k = map(int, lines[0].split())
    a = list(map(int, lines[1].split()))

    memo = {0: 0}

    def g(x):
        if x in memo:
            return memo[x]

        # Get reachable Grundy values
        reachable = {g(x - 1)}

        if x % 2 == 0:  # Even pile
            if k % 2 == 1:  # k is odd: split gives XOR of g(x/2)
                reachable.add(g(x // 2))
            else:  # k is even: split gives XOR of 0
                reachable.add(0)

        # Find mex (minimum excluded value)
        result = 0
        while result in reachable:
            result += 1

        memo[x] = result
        return result

    xor_sum = 0
    for val in a:
        xor_sum ^= g(val)

    return 'Kevin' if xor_sum != 0 else 'Nicky'

