def solve_grid(n, m, grid_data):
    # grid_data is list of strings

    # Try to find a valid 4-coloring
    # Based on the problem structure, we'll use backtracking with constraint checking

    # Color mapping: 1, 2, 3, 4
    colors = [1, 2, 3, 4]

    # Convert grid to 2D array (0 for unpainted, 1-4 for colored)
    color_grid = []
    for row in grid_data:
        r_grid = []
        for c in row:
            if c == '0':
                r_grid.append(-1)  # Unpainted
            else:
                r_grid.append(int(c))
        color_grid.append(r_grid)

    # Check if already colored cells have conflicts
    def check_conflict(r, c):
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m:
                    if color_grid[nr][nc] != -1 and color_grid[nr][nc] == color_grid[r][c]:
                        return True
        return False

    def backtracking(r, c):
        if r == n:
            return True

        next_r = r + 1 if c == m - 1 else r

        if color_grid[r][c] != -1:
            # Already colored, just check if valid
            if check_conflict(r, c):
                return False
            return backtracking(next_r, c)

