        if not line:
            break

        parts = line.split()
        if len(parts) < 2:
            continue

        try:
            N = int(parts[0])
            K = int(parts[1])
        except ValueError:
            continue

        # Special case: K=0 means no constraints
        if K == 0:
            results.append(' '.join(map(str, range(1, N + 1))))
            continue

        # If 2*K > N, it's impossible to satisfy all constraints
        # (too many numbers need to be far from their positions)
        if N < 2 * K:
            results.append("-1")
            continue

        # Backtracking to find lexicographically smallest valid permutation
        used = [False] * (N + 1)
        P = []

        def backtrack(pos):
            if pos > N:
                return True

            # Try smallest available number first (lexicographically smallest)
            for num in range(1, N + 1):
                if not used[num] and abs(num - pos) >= K:
                    used[num] = True
                    P.append(num)

                    if backtrack(pos + 1):
                        return True

                    P.pop()
                    used[num] = False

            return False

        if backtrack(1):
            results.append(' '.join(map(str, P)))
        else:
            results.append("-1")

    return '\n'.join(results)

