            need_hit = []
            for i, (h, a) in enumerate(bamboos):
                if h > max_h - a:
                    need_hit.append((a, h, i))

            if not need_hit:
                # Check if any bamboo exceeds max_h even after we've hit what we can
                # with remaining k hits on the absolute tallest ones
                for i, (h, a) in enumerate(bamboos):
                    if h > max_h:
                        # Bamboo is already too tall, use remaining k on it
                        hits = (h - max_h + p - 1) // p
                        bamboos[i] = (max(0, bamboos[i][0] - hits * p), a)
                        k -= hits
