    if x == 1:
        for i in range(n):
            if ops_left >= abs(new_arr[i]):
                new_arr[i] = 0
                ops_left -= abs(new_arr[i])
    else:
        # For x > 1, only elements divisible by x can be made exactly 0
        # Use greedy approach: zero out the cheapest elements first
        zeroable = []
        for i, a in enumerate(new_arr):
            if a % x == 0:
                cost = abs(a) // x
                zeroable.append((cost, i))

        # Sort by cost (cheapest first)
        zeroable.sort()

        for cost, i in zeroable:
            if ops_left >= cost:
                new_arr[i] = 0
                ops_left -= cost

    # Convert to string
    return " ".join(map(str, new_arr)) + "\n"


