    # DFS to find cycle
    def dfs(start_node):
        disc = set()
        parent = {start_node: None}
        stack = [(start_node, iter(adj[start_node]))]

        while stack:
            v, neighbors = stack[-1]

            try:
                neighbor = next(neighbors)
            except StopIteration:
                stack.pop()
                continue

            if neighbor not in disc:
                disc.add(neighbor)
                parent[neighbor] = v
                stack.append((neighbor, iter(adj[neighbor])))
            elif neighbor != parent[v]:
                # Back edge found - cycle detected
                cycle = []
                curr = neighbor
                while True:
                    cycle.append(curr)
                    if curr == v:
                        break
                    curr = parent[curr]
                return cycle

        return None

    # Try starting from each vertex to find a cycle
    for start in range(1, n + 1):
        start_disc = set()
        start_parent = {start: None}
        cycle_start = start
