            except StopIteration:
                stack.pop()
                continue

            if neighbor not in start_disc:
                start_disc.add(neighbor)
                start_parent[neighbor] = v
                stack.append((neighbor, iter(adj[neighbor])))
            elif neighbor != start_parent.get(v):
                # Back edge found
                actual_cycle = []
                curr = neighbor
                while curr != v:
                    actual_cycle.append(curr)
                    curr = start_parent[curr]
                return f"2\n{len(actual_cycle)}\n" + " ".join(map(str, actual_cycle)) + "\n"

    # BFS to find independent set
    levels = {}
    queue = deque([1])
    levels[1] = 0

    while queue:
        v = queue.popleft()
        for neighbor in adj[v]:
            if neighbor not in levels:
                levels[neighbor] = levels[v] + 1
                queue.append(neighbor)

    # Odd levels form independent set
    odd_levels = [v for v in levels if levels[v] % 2 == 1]
    even_levels = [v for v in levels if levels[v] % 2 == 0]

    result = odd_levels if len(odd_levels) >= k else even_levels

    return f"1\n{k}\n" + " ".join(map(str, result)) + "\n"

