        # Apply operations
        for op in ops:
            if op == 'R':
                # Cyclic shift columns right
                for v in range(1, n + 1):
                    _, old_c = positions[v]
                    new_c = (old_c + 1) % n
                    positions[v] = (positions[v][0], new_c)

            elif op == 'L':
                # Cyclic shift columns left
                for v in range(1, n + 1):
                    _, old_c = positions[v]
                    new_c = (old_c - 1) % n
                    positions[v] = (positions[v][0], new_c)

            elif op == 'D':
                # Cyclic shift rows down
                for v in range(1, n + 1):
                    old_r, _ = positions[v]
                    new_r = (old_r + 1) % n
                    positions[v] = (new_r, positions[v][1])

            elif op == 'U':
                # Cyclic shift rows up
                for v in range(1, n + 1):
                    old_r, _ = positions[v]
                    new_r = (old_r - 1) % n
                    positions[v] = (new_r, positions[v][1])

            elif op == 'I':
                # Inverse each row
                for old_r in range(n):
                    # Get current row values
                    row_vals = []
                    for old_c in range(n):
                        val = positions[old_r * n + old_c + 1]
                        row_vals.append(val)

                    # Compute inverse: inverse[q[i]] = i means q[position of value (i+1)] = i
                    # Find position of each value in the row (0-indexed)
                    inv = [0] * n
                    for v_pos, val in enumerate(row_vals):
                        inv[val - 1] = v_pos

                    # Update positions for each value in this row
                    for old_c in range(n):
                        val = row_vals[old_c]
                        if inv[val - 1] != old_c:
                            # Value at position (old_r, old_c) moves to (old_r, inv[val-1])
                            new_c = inv[val - 1]
                            positions[val] = (old_r, new_c)
                            old_r, old_c = positions[val]

            elif op == 'C':
                # Inverse each column
                for old_c in range(n):
                    # Get current column values
                    col_vals = []
                    for old_r in range(n):
                        val = positions[old_r * n + old_c + 1]
                        col_vals.append(val)

                    # Compute inverse
                    inv = [0] * n
                    for v_pos, val in enumerate(col_vals):
                        inv[val - 1] = v_pos

                    # Update positions for each value in this column
                    for old_r in range(n):
                        val = col_vals[old_r]
                        if inv[val - 1] != old_r:
                            # Value at position (old_r, old_c) moves to (inv[val-1], old_c)
                            new_r = inv[val - 1]
                            positions[val] = (new_r, old_c)
                            old_r, old_c = positions[val]

