def solution(input_string):
    """
    Solves the Walrusland lucky tickets problem.
    Finds minimum x * y (series count * tickets per series) such that at least w lucky tickets exist.
    A ticket (a, b) is lucky if a * b = rev(a) * rev(b).
    """
    try:
        parts = input_string.strip().split()
        if len(parts) < 3:
            return "-1"
        maxx, maxy, w = map(int, parts)
    except:
        return "-1"

    def rev(n):
        """Reverses a number in decimal system, removing leading zeros."""
        s = str(n)
        return int(s[::-1])

    # Precompute rev values for efficiency
    max_val = max(maxx, maxy)
    rev_cache = [rev(i) for i in range(max_val + 1)]

    # We need to find minimum x * y such that count of lucky tickets >= w
    # Iterate through possible x and y values
    for x in range(1, maxx + 1):
        for y in range(1, maxy + 1):
            count = 0
            for a in range(1, x + 1):
                ra = rev_cache[a]
                for b in range(1, y + 1):
                    if a * b == ra * rev_cache[b]:
                        count += 1
            if count >= w:
                # Since we iterate x from 1 to maxx and y from 1 to maxy,
                # we prioritize smaller x first, then smaller y.
                # This helps minimize x*y.
                return f"{x} {y}"

    return "-1"

from collections import deque

def solution(s):
    n = int(s.strip())

    if n == 0:
        return "0"

    # BFS to find minimum operations
    # For each number, we can subtract any of its digits
    queue = deque([(n, 0)])  # (current_number, steps)
    visited = {n}

    while queue:
        current, steps = queue.popleft()

        if current == 0:
            return str(steps)

        digit_chars = set(str(current))

        for digit in digit_chars:
            subtract_val = int(digit)
            new_val = current - subtract_val

            if new_val >= 0 and new_val not in visited:
                visited.add(new_val)
                queue.append((new_val, steps + 1))

    return str(steps)

def solution(input_str):
    lines = input_str.strip().split('\n')
    n, m = map(int, lines[0].split())

    attempts = []
    for i in range(1, m + 1):
        parts = lines[i].split()
        attempts.append((parts[0], int(parts[1])))

    # Precompute bit masks for each attempt
    masks = []
    for s, _ in attempts:
        mask = 0
        for i, c in enumerate(s):
            if c == '1':
                mask |= (1 << i)
        masks.append(mask)

    targets = [c for _, c in attempts]

    # Split into left and right halves for meet-in-the-middle
    mid = n // 2

    # Generate all combinations for left half
    left_patterns = []

    def gen_left(pos, val):
        if pos == mid:
            # Compute matches for each attempt
            matches = []
            for i in range(m):
                matches.append(bin(val & masks[i]).count('1'))
            left_patterns.append((val, matches))
            return
        for bit in [0, 1]:
            gen_left(pos + 1, val | (bit << pos))

    gen_left(0, 0)

    # Generate all combinations for right half
    right_patterns = []

    def gen_right(pos, val):
        if pos == n:
            # Compute matches for each attempt (only bits from right half)
            matches = []
            for i in range(m):
                # Shift to get right half part
                from_second_half = ((val >> mid) << mid) & ((1 << (n - mid)) - 1)
                matches.append(bin((from_second_half << (mid - pos)) & masks[i]).count('1'))
            right_patterns.append((val, matches))
            return
        for bit in [0, 1]:
            gen_right(pos + 1, val | (bit << pos))

    gen_right(0, 0)

    # Count valid combinations
    count = 0
    for l_val, l_matches in left_patterns:
        # Filter out impossible left patterns
        if any(l_matches[i] > targets[i] for i in range(m)):
            continue
        for r_val, r_matches in right_patterns:
            # Check if combined matches equal targets
            if all(l_matches[i] + r_matches[i] == targets[i] for i in range(m)):
                count += 1

    return str(count)

