        parts = lines[i].strip().split()
        s_i = parts[0]
        m_i = int(parts[1])
        phones.append((s_i, m_i))

    # Calculate original total cost (without any speed dial)
    total_original_cost = sum(m_i * len(s_i) for s_i, m_i in phones)

    # Generate all possible candidate speed dial strings
    candidates = set()
    for s_i, m_i in phones:
        for length in range(1, len(s_i) + 1):
            for start in range(len(s_i) - length + 1):
                candidates.add(s_i[start:start+length])

    best_savings = 0

    # For each candidate, calculate how much cost we can save
    for cand in candidates:
        saving = 0
        for s_i, m_i in phones:
            # Find longest matching prefix between s_i and cand
            L = 0
            for j in range(min(len(s_i), len(cand)) + 1):
                if s_i[:j] == cand[:j]:
                    L = j if L == 0 else L

            if L > 0:
                saving += m_i * L

        best_savings = max(best_savings, saving)

    # Final cost = original cost - maximum savings possible
    final_cost = total_original_cost - best_savings
    return str(int(final_cost))
